"""Render question/answer tables and methodology without recomputing scores."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent/'results'/'translation_e2e'
CONFIG=json.loads(r'''{"title": "\uc9c8\ubb38\u00b7\ub2f5\ubcc0 \ubc88\uc5ed \ud3c9\uac00 \uacb0\uacfc", "summary": "\uc885\ud569 \uacb0\uacfc", "methodq": "\uc9c8\ubb38 \ubc88\uc5ed \uce21\uc815 \ubc29\uc2dd\uacfc \ucc44\ud0dd \uc774\uc720", "qtext": "\uc601\uc5b4 \uc9c8\ubb38\uc744 \uc2dc\uc2a4\ud15c\uc774 \ud55c\uad6d\uc5b4\ub85c \ubc88\uc5ed\ud55c \ubb38\uc7a5\uacfc \uc0ac\uc6a9\uc790\uac00 \uc81c\uacf5\ud55c \uae30\uc900 \ud55c\uad6d\uc5b4 \ubb38\uc7a5\uc744 \ube44\uad50\ud569\ub2c8\ub2e4. \uae30\uc900 \ubb38\uc7a5\uc740 \uc218\uc815\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.\n\n**\uc9c8\ubb38 \ubc88\uc5ed \uc810\uc218 = BERTScore F1 \u00d7 100**\n\n**\ucc44\ud0dd \uc774\uc720:** \u2018\uae30\uc219\uc0ac\ub294 \uc5b4\ub5bb\uac8c \uc2e0\uccad\ud558\ub098\uc694?\u2019\uc640 \u2018\uc5b4\ub5bb\uac8c \uae30\uc219\uc0ac\ub97c \uc2e0\uccad\ud560 \uc218 \uc788\uc744\uae4c\uc694?\u2019\ucc98\ub7fc \ub73b\uc740 \ube44\uc2b7\ud558\uc9c0\ub9cc \ud45c\ud604\uc774 \ub2e4\ub978 \ubb38\uc7a5\uc744 \ub2e8\uc21c\ud55c \uae00\uc790 \uc77c\uce58\ubcf4\ub2e4 \uc720\uc5f0\ud558\uac8c \ube44\uad50\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud588\uc2b5\ub2c8\ub2e4.\n\nBLEU\ub294 \ub2e8\uc5b4\u00b7\ud45c\ud604\uc758 \uc77c\uce58 \uc815\ub3c4\ub97c \ud655\uc778\ud558\ub294 \ubcf4\uc870 \uc9c0\ud45c\uc785\ub2c8\ub2e4. \uc9c8\ubb38 \uc810\uc218\uc5d0 \ud569\uc0b0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ubb38\uc790 \ub2e8\uc704 BLEU-4, exponential smoothing, effective_order=True \uc124\uc815\uc73c\ub85c \uacc4\uc0b0\ud588\uc2b5\ub2c8\ub2e4.", "methoda": "\ub2f5\ubcc0 \ubc88\uc5ed \uce21\uc815 \ubc29\uc2dd\uacfc \ucc44\ud0dd \uc774\uc720", "atext": "\uc774 \ud3c9\uac00\uc5d0\uc11c\ub294 \uc11c\ube44\uc2a4\uac00 \ub9cc\ub4e0 \ud55c\uad6d\uc5b4 \ub2f5\ubcc0\uacfc, \uadf8 \ub2f5\ubcc0\uc744 \uc2e4\uc81c\ub85c \ubc88\uc5ed\ud55c \uc601\uc5b4 \ub2f5\ubcc0\uc744 \ube44\uad50\ud569\ub2c8\ub2e4.\n\n**\ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4 \uc810\uc218 = BERTScore F1 \u00d7 100**\n\n\uc608\ub97c \ub4e4\uc5b4 F1\uc774 0.7215\uc774\uba74 \ud45c\uc5d0\ub294 72.15\uc810\uc73c\ub85c \ud45c\uc2dc\ud569\ub2c8\ub2e4. \ubcc4\ub3c4\uc758 \uc810\uc218\ub098 \uac00\uc911\uce58\ub97c \ud569\uc0b0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\nBERTScore\ub294 \ubb38\uc7a5 \uc18d \ub2e8\uc5b4\ub97c \ubb38\ub9e5\uc744 \ubc18\uc601\ud55c \uc22b\uc790 \ud45c\ud604\uc73c\ub85c \ubc14\uafb8\uace0, \ub450 \ubb38\uc7a5 \uc0ac\uc774\uc5d0\uc11c \ube44\uc2b7\ud55c \ub2e8\uc5b4\ub97c \ucc3e\uc544 \ube44\uad50\ud569\ub2c8\ub2e4. P\ub294 \uc601\uc5b4 \ub2f5\ubcc0\uc758 \ub2e8\uc5b4\uac00 \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uacfc \uc5bc\ub9c8\ub098 \uc798 \ub300\uc751\ud558\ub294\uc9c0, R\uc740 \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uc758 \ub2e8\uc5b4\uac00 \uc601\uc5b4 \ub2f5\ubcc0\uacfc \uc5bc\ub9c8\ub098 \uc798 \ub300\uc751\ud558\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. F1\uc740 \ub450 \uac12\uc744 \ud568\uaed8 \ubc18\uc601\ud55c \uc810\uc218\uc785\ub2c8\ub2e4.\n\n**\ucc44\ud0dd \uc774\uc720:** \ud55c\uad6d\uc5b4\uc640 \uc601\uc5b4\ub294 \ud45c\ud604\uacfc \uc5b4\uc21c\uc774 \ub2e4\ub974\ubbc0\ub85c \ub2e8\uc5b4\uac00 \ub611\uac19\uc774 \uc4f0\uc600\ub294\uc9c0\ub9cc \ube44\uad50\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub450 \uc5b8\uc5b4\ub97c \ucc98\ub9ac\ud558\ub294 \ubaa8\ub378\ub85c \ubb38\ub9e5\uc758 \uc720\uc0ac\ub3c4\ub97c \uacc4\uc0b0\ud558\uace0, \ubcc4\ub3c4\uc758 \uc601\uc5b4 \uc815\ub2f5 \ubb38\uc7a5\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \uc2e4\uc81c \uc6d0\ubb38\uacfc \ubc88\uc5ed\ubb38\uc744 \ube44\uad50\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud588\uc2b5\ub2c8\ub2e4.\n\n**\uc8fc\uc758:** \uc774 \ud55c\uc601 \uc9c1\uc811 \ube44\uad50\ub294 \ud0d0\uc0c9\uc801\uc778 \uc720\uc0ac\ub3c4 \uce21\uc815\uc785\ub2c8\ub2e4. \uc22b\uc790\u00b7\ud1b5\ud654\u00b7\ud589\uc815 \uc6a9\uc5b4 \uc624\uc5ed\uc744 \ub193\uce60 \uc218 \uc788\uc73c\ubbc0\ub85c 71.25\uc810\uc774 \u2018\ubc88\uc5ed \uc815\ud655\ub3c4 71.25%\u2019\ub77c\ub294 \ub73b\uc740 \uc544\ub2d9\ub2c8\ub2e4.", "original": "\uae30\uc874 \ub2f5\ubcc0 \uc885\ud569 = \uc758\ubbf8 \ubcf4\uc874 \u00d7 0.4 + \ud575\uc2ec\uc815\ubcf4 \ubcf4\uc874 \u00d7 0.6. \uc758\ubbf8 \ubcf4\uc874\uc740 gpt-4o \uace0\uc815 rubric\uc758 \uc790\ub3d9 \ud3c9\uac00 \ucd94\uc815\uce58\uc774\uba70, \ud575\uc2ec\uc815\ubcf4 \ubcf4\uc874\uc740 \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uc5d0\uc11c \ucd94\ucd9c\ud55c \ud56d\ubaa9 \uc911 \uc601\uc5b4\uc5d0 \ubcf4\uc874\ub41c \ube44\uc728\uc785\ub2c8\ub2e4. \uc22b\uc790\u00b7\uae08\uc561\u00b7\uc11c\ub958\u00b7\uc870\uac74\u00b7\ud589\uc815 \uc6a9\uc5b4 \uc624\uc5ed\uc744 \uc804\uccb4 \ubb38\ub9e5 \uc720\uc0ac\ub3c4\uc5d0\uc11c \ub193\uce58\uc9c0 \uc54a\uae30 \uc704\ud574 \ucc44\ud0dd\ud588\uc2b5\ub2c8\ub2e4. COMET \uc810\uc218\uac00 \uc544\ub2c8\uba70 \uc790\ub3d9 \ucd94\ucd9c\u00b7\ud310\uc815\uc740 \uc804\ubb38\uac00 \uac80\ud1a0\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.", "limit": "\uc9c8\ubb38 \ud3c9\uade0\uc740 88.07\uc810, \ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4 \ud3c9\uade0\uc740 71.25\uc810\uc785\ub2c8\ub2e4. \uc9c8\ubb38\uc740 \ud55c\uad6d\uc5b4\ub07c\ub9ac, \ub2f5\ubcc0\uc740 \ud55c\uad6d\uc5b4\uc640 \uc601\uc5b4\ub97c \ube44\uad50\ud558\ubbc0\ub85c \ub450 \uc810\uc218\ub97c \ud569\uce5c \ub2e8\uc77c \uc810\uc218\ub294 \uacc4\uc0b0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub2f5\ubcc0\uc740 \ud3c9\uade0 70\uc810 \uc774\uc0c1\uc774\uc9c0\ub9cc 20\ubb38\ud56d \ubaa8\ub450 70\uc810 \uc774\uc0c1\uc740 \uc544\ub2d9\ub2c8\ub2e4.", "qh": ["ID", "\uc601\uc5b4 \uc9c8\ubb38", "\uae30\uc900 \ud55c\uad6d\uc5b4", "\uc2e4\uc81c \ud55c\uad6d\uc5b4 \ubc88\uc5ed", "BLEU", "BERTScore F1", "\uc9c8\ubb38 \uc810\uc218"], "ah": ["ID", "\uc601\uc5b4 \uc9c8\ubb38 / \uc804\uccb4 \ub2f5\ubcc0", "BERTScore P", "BERTScore R", "BERTScore F1", "\ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4 \uc810\uc218", "70\uc810 \uc774\uc0c1"], "sh": ["\ud3c9\uac00 \ud56d\ubaa9", "\ud3c9\uade0 / 100", "\uc801\uc6a9 \uae30\uc900", "\uae30\uc900 \uc774\uc0c1 \ubb38\ud56d"], "names": ["\uc9c8\ubb38 \ubc88\uc5ed", "\ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4"], "qtitle": "\uc9c8\ubb38 \ubc88\uc5ed \uc804\uccb4 20\ubb38\ud56d \uacb0\uacfc", "atitle": "\ub2f5\ubcc0 \ubc88\uc5ed \uc804\uccb4 20\ubb38\ud56d \uacb0\uacfc", "end": "\uacc4\uc0b0 \uc124\uc815: bert-base-multilingual-cased, layer 9, CPU, IDF \ubbf8\uc0ac\uc6a9, baseline rescaling \ubbf8\uc0ac\uc6a9. \uc6d0\uc2dc \uc720\uc0ac\ub3c4\ub294 \uc624\uc5ed\uc774 \uc788\uc5b4\ub3c4 \ub192\uac8c \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubaa8\ub4e0 \ub2f5\ubcc0\uc740 \ud1a0\ud070 \ud55c\ub3c4 512 \uc774\ub0b4\uc600\uace0, \uc810\uc218 \ud558\ud55c\u00b7\uac00\uc0b0\uc810\u00b7\ubb38\ud56d \uc81c\uc678\ub294 \uc801\uc6a9\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc800\uc7a5\ub41c \uc2e4\uc81c \ucd9c\ub825\uc73c\ub85c \uacc4\uc0b0\ud588\uc73c\uba70 \uc774\ubc88 \ubb38\uc11c \uc218\uc815\uc5d0\uc11c \ubc88\uc5ed \uc7ac\uc2e4\ud589\uc774\ub098 \uc810\uc218 \ubcc0\uacbd\uc740 \ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.", "yes": "\uc608", "no": "\uc544\ub2c8\uc624"}''')

def render():
    d=json.loads((OUT/'results.json').read_text(encoding='utf-8'))
    s=json.loads((OUT/'answer-similarity-results.json').read_text(encoding='utf-8'))
    rows=d['rows']; extra={r['id']:r for r in s['rows']}
    assert len(rows)==len(extra)==20
    q=d['summary']['questions']; a=d['summary']['answers']; c=CONFIG
    def table(headers,values):
        def cell(v): return str(v).replace('|',r'\|').replace('\n','<br>')
        return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(cell(v) for v in row)+' |' for row in values])
    overview=table(c['sh'],[
        [c['names'][0],f"**{q['average_semantic_score']:.2f}**",80,f"{q['above_80_count']}/20 (95%)"],
        [c['names'][1],f"**{s['average']:.2f}**",70,f"{s['above_70_count']}/20 (60%)"]])
    questions=table(c['qh'],[[r['id'],r['english_question'],r['reference'],r['system_translation'],f"{r['smoothed_bleu']:.2f}",f"{r['bertscore']:.4f}",f"**{r['question_semantic_score']:.2f}**"] for r in rows])
    answers=[]
    for r in rows:
        e=extra[r['id']]
        answers.append([r['id'],f"[{r['english_question']}](details.md#item-{r['id']})",f"{e['precision']:.4f}",f"{e['recall']:.4f}",f"{e['f1']:.4f}",f"**{e['similarity_score']:.2f}**",c['yes'] if e['similarity_score']>=70 else c['no']])
    parts=['# '+c['title'],'## 1. '+c['summary'],overview,c['limit'],'## 2. '+c['methodq'],c['qtext'],'## 3. '+c['qtitle'],questions,'## 4. '+c['methoda'],c['atext'],'## 5. '+c['atitle'],table(c['ah'],answers),'## 6. Settings / Reproduction','[BERTScore](https://github.com/Tiiiger/bert_score) | [Baseline rescaling](https://github.com/Tiiiger/bert_score/blob/master/journal/rescale_baseline.md)','[Original JSON](results.json) | [Answer score JSON](answer-similarity-results.json) | [Full answer pairs](details.md)','python evaluation/build_translation_combined_report.py',c['end']]
    text='\n\n'.join(parts)+'\n'
    assert '\ufffd' not in text
    assert len(questions.splitlines())==22
    assert len(table(c['ah'],answers).splitlines())==22
    (OUT/'answer-similarity-report.md').write_text(text,encoding='utf-8')
    print('Report updated and validated: 20 question rows, 20 answer rows, summary and methods.')

if __name__=='__main__': render()

